const columns = [
  {
    field: 'status',
    headerName: 'Status',
    renderCell: (row) => <StatusChip status={row.status} />
  },
  {
    field: 'progress',
    headerName: 'Progress',
    renderCell: (row) => <ProgressBar value={row.progress} />
  },
  {
    field: 'actions',
    headerName: 'Actions',
    renderCell: (row) => (
      <ButtonCell 
        label="View" 
        onClick={() => handleView(row)} 
        variant="primary"
      />
    )
  }
];

